/**
 * Parity: the ISA against the reference implementation.
 *
 * ## The chain this test closes
 *
 * `fixtures/isa-parity.json` is generated by **running
 * `arcade-engine/src/nature.ts` directly** — `scripts/gen-parity.ts`, SplitMix64
 * from a fixed seed, 400 cases. `nature.ts` is in turn proved against the
 * `asamanthinks-platform` reference implementation by `arcade-engine`'s own
 * 200-case fixture (`arcade-engine/test/fixtures/tera-parity.json`, tolerance
 * 1e-6).
 *
 * So this is not a two-way comparison against a second thing I wrote. It is the
 * third link in:
 *
 *     platform reference  ──▶  arcade-engine  ──▶  vortex-vm (published here as @aamt/tera)
 *
 * and the reason to spell that out is that a reimplementation is only worth
 * having if it is *provably the same function*. A lookalike that drifts by a few
 * ulps corrupts a world hash in a way no test on its own output would catch,
 * because both sides would be consistently wrong together.
 *
 * ## Why the sample is boundary-heavy
 *
 * The generated population deliberately over-samples the two places the
 * implementations can actually disagree:
 *
 * - **`kappaProj`'s saturating branch.** A naive uniform-shift-then-clamp
 *   projection diverges from the active-set version by up to **0.081** on
 *   saturating inputs. Saturation is not an edge case — it is 39.8% of draws at
 *   `κ = 0.05` and approaches 100% at `κ ≥ 0.7`, so a uniform sample would
 *   systematically under-test the common path.
 * - **Axis ties.** Those are the walls of the braid arrangement, and the only
 *   place `chirality` returns 0.
 *
 * The integer-valued readouts are compared for **exact** equality, not to
 * tolerance. A `meji` index is a threshold result; if two implementations
 * disagree on it they disagree about which of 16 cells a state is in, and no
 * numeric tolerance expresses that.
 */

import { describe, expect, it } from 'vitest';
import fixtures from './fixtures/isa-parity.json';
import {
  coherence,
  entropy,
  axisEntropy,
  chirality,
  chiralMargin,
  chiralAddress,
  frDist,
  geodesic,
  kappaProj,
  makeReg,
  mejiDist,
  mejiIndex,
  oduIndex,
  oxChirality,
  recoverTera,
  resonantIntegrity,
  REFERENCE_TRANSCENDENTALS,
  type Tera,
} from '../src/alu';

interface Case {
  a: [number, number, number, number];
  b: [number, number, number, number];
  kappa: number;
  d_fr: number;
  geodesic_mid: number[];
  chir_b: number;
  proj: number[];
  scale: number;
  ri: number;
  coherence: number;
  entropy: number;
  entropy_axes: number[];
  meji: number;
  odu: number;
  dominant: number;
  chir: number;
  dist16: number[];
  recovered: number[];
}

const TOL = fixtures.tolerance;
const cases = fixtures.cases as Case[];
const tup = (x: readonly number[]): Tera => [x[0] ?? 0, x[1] ?? 0, x[2] ?? 0, x[3] ?? 0];

describe('fixture set', () => {
  it('has cases to check', () => {
    expect(cases.length).toBe(400);
  });

  it('actually samples the two disagreement sites', () => {
    // If either count collapses, the sampler regressed and this file would
    // quietly stop testing the branches it exists to test.
    const boundary = cases.filter((c) => c.a.some((x) => x < 1e-3 || x > 1 - 1e-3)).length;
    const ties = cases.filter((c) => {
      const [t, e, r, a] = c.a;
      return Math.abs(t - e) < 1e-3 || Math.abs(r - a) < 1e-3 || Math.abs(t - r) < 1e-3;
    }).length;
    expect(boundary, 'boundary-heavy cases').toBeGreaterThan(50);
    expect(ties, 'tie-heavy cases').toBeGreaterThan(50);
  });

  it('includes cases where the projection saturates', () => {
    // A projection that pins an axis at the ceiling is the active-set branch.
    const saturating = cases.filter((c) => c.proj.some((x) => x >= 1)).length;
    expect(saturating, 'saturating projections').toBeGreaterThan(20);
  });
});

describe('geometry — θ-native', () => {
  it('frDist matches the reference', () => {
    let worst = 0;
    let at = 0;
    for (let i = 0; i < cases.length; i++) {
      const c = cases[i]!;
      const d = Math.abs(frDist(makeReg(tup(c.a)), makeReg(tup(c.b))) - c.d_fr);
      if (d > worst) {
        worst = d;
        at = i;
      }
    }
    // The formula is the same term for term. Anything above float noise here
    // means one of the two had been edited.
    expect(worst, `worst at case ${at}`).toBeLessThan(TOL);
  });

  it('geodesic midpoint matches the reference', () => {
    let worst = 0;
    for (const c of cases) {
      const mid = geodesic(makeReg(tup(c.a)), makeReg(tup(c.b)), 0.5);
      const v = [0, 1, 2, 3].map((d) => REFERENCE_TRANSCENDENTALS.fromTheta(mid.theta[d] ?? 0));
      for (let d = 0; d < 4; d++) worst = Math.max(worst, Math.abs((v[d] ?? 0) - (c.geodesic_mid[d] ?? 0)));
    }
    expect(worst).toBeLessThan(TOL);
  });
});

describe('conservation — log-native', () => {
  it('kappaProj matches the reference projectOntoKappa', () => {
    let worst = 0;
    let at = 0;
    for (let i = 0; i < cases.length; i++) {
      const c = cases[i]!;
      const mine = kappaProj(tup(c.a), c.kappa);
      for (let d = 0; d < 4; d++) {
        const delta = Math.abs((mine[d] ?? 0) - (c.proj[d] ?? 0));
        if (delta > worst) {
          worst = delta;
          at = i;
        }
      }
    }
    expect(worst, `worst at case ${at}`).toBeLessThan(TOL);
  });

  it('the reference scale factor is the same fourth-root correction', () => {
    for (const c of cases) {
      const p = (c.a[0] ?? 0) * (c.a[1] ?? 0) * (c.a[2] ?? 0) * (c.a[3] ?? 0);
      expect(Math.abs(Math.pow(c.kappa / Math.max(1e-12, p), 0.25) - c.scale)).toBeLessThan(TOL);
    }
  });
});

describe('readouts — v-native, O(d)', () => {
  it('resonantIntegrity matches', () => {
    let worst = 0;
    for (const c of cases) worst = Math.max(worst, Math.abs(resonantIntegrity(makeReg(tup(c.a))) - c.ri));
    expect(worst).toBeLessThan(TOL);
  });

  it('coherence matches', () => {
    let worst = 0;
    for (const c of cases) worst = Math.max(worst, Math.abs(coherence(makeReg(tup(c.a))) - c.coherence));
    expect(worst).toBeLessThan(TOL);
  });

  it('entropy matches, in total and per axis', () => {
    let worst = 0;
    for (const c of cases) {
      worst = Math.max(worst, Math.abs(entropy(makeReg(tup(c.a))) - c.entropy));
      // Per axis, read back **through the register** rather than off the raw
      // input. Reading the raw input would compare the reference to itself and
      // pass no matter what the register did — which is exactly the mistake this
      // assertion shape exists to prevent.
      const reg = makeReg(tup(c.a));
      for (let d = 0; d < 4; d++) worst = Math.max(worst, Math.abs(axisEntropy(reg.v[d] ?? 0) - (c.entropy_axes[d] ?? 0)));
    }
    expect(worst).toBeLessThan(TOL);
  });

  it('the register keeps v exact, so readouts are not amplified by the θ round trip', () => {
    // Regression guard for the design change documented on `TeraReg`. Storing
    // only `θ` and deriving `v` through `sin²(θ/2)` costs 1.47e-7 in the lanes,
    // and `axisEntropy`'s gradient `log₂((1−v)/v)` is about 20 at `v = 1e-6`, so
    // a boundary axis turns that into ~6e-6 of entropy error — six times the
    // machine's own tolerance, from an operation that is nominally only a
    // coordinate change.
    const boundary = cases.find((c) => c.a.some((x) => x < 1e-3));
    expect(boundary, 'the sample contains boundary cases').toBeDefined();
    const v = tup(boundary!.a);
    const reg = makeReg(v);
    for (let d = 0; d < 4; d++) expect(reg.v[d]).toBe(v[d]);
    // And the gradient that made this matter, measured rather than asserted.
    const tightest = Math.min(...v.filter((x) => x > 0 && x < 1));
    const gradient = Math.abs(Math.log2((1 - tightest) / tightest));
    expect(gradient).toBeGreaterThan(1);
  });
});

describe('address and tag — exact, because they are integers', () => {
  it('meji index matches the reference bit ordering exactly', () => {
    for (const c of cases) {
      expect(mejiIndex(makeReg(tup(c.a)))).toBe(c.meji);
      // `nature.ts` reaches the same cell by argmax over the distribution; the
      // ISA thresholds at ½. Agreement between the two is the lossless-recovery
      // theorem showing up as a test.
      expect(mejiIndex(makeReg(tup(c.a)))).toBe(c.dominant);
    }
  });

  it('odu index matches exactly', () => {
    for (const c of cases) expect(oduIndex(makeReg(tup(c.a)))).toBe(c.odu);
  });

  it('chirality matches, including the sign and the zero', () => {
    for (const c of cases) expect(chirality(makeReg(tup(c.a)))).toBe(c.chir);
  });

  it('agrees with the reference on chirality for the second vector too', () => {
    // The generator records `b`'s chirality independently of `a`'s, so this is a
    // genuine second sample rather than the same vector read twice.
    let achiral = 0;
    for (const c of cases) {
      expect(chirality(makeReg(tup(c.b)))).toBe(c.chir_b);
      if (c.chir_b === 0) achiral++;
    }
    // The tie-heavy sampler should produce some exact ties. If it never does,
    // the zero branch of `chirality` is untested.
    expect(achiral, 'exact ties in the sample').toBeGreaterThan(0);
  });
});

describe('the distribution is a lossless encoding', () => {
  it('mejiDist matches the reference distribution', () => {
    let worst = 0;
    for (const c of cases) {
      const mine = mejiDist(makeReg(tup(c.a)));
      for (let k = 0; k < 16; k++) worst = Math.max(worst, Math.abs((mine[k] ?? 0) - (c.dist16[k] ?? 0)));
    }
    expect(worst).toBeLessThan(TOL);
  });

  it('recoverTera matches the reference', () => {
    let worst = 0;
    for (const c of cases) {
      const mine = recoverTera(c.dist16);
      for (let d = 0; d < 4; d++) worst = Math.max(worst, Math.abs((mine[d] ?? 0) - (c.recovered[d] ?? 0)));
    }
    expect(worst).toBeLessThan(TOL);
  });

  it('recovers the register it was built from', () => {
    // The load-bearing theorem: a 16-cell histogram is a *lossless* encoding of
    // a continuous 4-D state, not a lossy summary of it. If this ever fails,
    // "16 slots are a sufficient record of a nature" is false.
    let worst = 0;
    for (const c of cases) {
      const back = recoverTera(mejiDist(makeReg(tup(c.a))));
      for (let d = 0; d < 4; d++) worst = Math.max(worst, Math.abs((back[d] ?? 0) - (c.a[d] ?? 0)));
    }
    expect(worst, 'round trip through 16 cells').toBeLessThan(TOL);
  });
});

describe('the 5-bit joint address', () => {
  it('is the meji index with the chirality bit appended', () => {
    for (const c of cases) {
      const reg = makeReg(tup(c.a));
      expect(chiralAddress(reg)).toBe((mejiIndex(reg) << 1) | (oxChirality(reg) > 0 ? 1 : 0));
      expect(chiralAddress(reg)).toBeLessThan(32);
    }
  });

  it('splits every meji cell exactly in half', () => {
    // Enumerated over all 24 chambers × 16 cells upstream: the orderings
    // compatible with cell k form S_J × S_Jᶜ ≤ S₄, whose sign character is
    // surjective, so the kernel has index 2 and the split is 12/12, 6/6, 2/2.
    const counts = new Map<number, { plus: number; minus: number }>();
    const sample = cases.map((c) => makeReg(tup(c.a)));
    for (const reg of sample) {
      const m = mejiIndex(reg);
      const entry = counts.get(m) ?? { plus: 0, minus: 0 };
      if (oxChirality(reg) > 0) entry.plus++;
      else entry.minus++;
      counts.set(m, entry);
    }
    // Only cells with enough samples can be checked for balance, and a balanced
    // cell must have both signs represented.
    for (const [cell, entry] of counts) {
      if (entry.plus + entry.minus >= 8) {
        expect(Math.min(entry.plus, entry.minus), `cell ${cell} is one-sided`).toBeGreaterThan(0);
      }
    }
  });
});

describe('chirality margin', () => {
  it('is zero on an exact tie and positive away from one', () => {
    expect(chiralMargin(makeReg([0.5, 0.5, 0.5, 0.5]))).toBe(0);
    expect(chiralMargin(makeReg([0.9, 0.6, 0.3, 0.1]))).toBeGreaterThan(0);
  });

  it('is Σ_κ-invariant, because it is a function of ratios only', () => {
    // A uniform positive rescale leaves every log-ratio unchanged, so the margin
    // is invariant where the address is not. The residual is the transcendental
    // table's error (~4e-8), which is why this asserts at the machine's own 1e-6
    // rather than at table precision — the claim being made is about the
    // function, not about the port.
    const before = chiralMargin(makeReg([0.9, 0.6, 0.3, 0.1]));
    const after = chiralMargin(makeReg([0.45, 0.3, 0.15, 0.05]));
    expect(Math.abs(before - after)).toBeLessThan(TOL);
    expect(before).toBeGreaterThan(0.1);
  });
});
